"""Build TRMNL source, credits and preview data from the verified catalogue."""
import html, json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
catalogue=json.loads((ROOT/'data/catalogue.json').read_text())
entries=catalogue['entries']
compact=[{k:e[k] for k in ('id','title','theme','magnification','credit','license','license_url','source_page','local_image')} for e in entries]
template=(ROOT/'scripts/transform.template.js').read_text()
(ROOT/'src/transform.js').write_text(template.replace('__CATALOGUE__',json.dumps(compact,ensure_ascii=False,separators=(',',':'))))
for layout in ('full','half_horizontal','half_vertical','quadrant'):
 (ROOT/f'src/{layout}.liquid').write_text('<div class="layout unseen-layout">{{ unseen_exhibit }}</div>\n{{ unseen_titlebar }}\n')
(ROOT/'data/ping.json').write_text(json.dumps({'collection':'Unseen','version':catalogue['version']},separators=(',',':'))+'\n')
credits=['# Unseen image credits\n',f'{len(entries)} scanning electron micrographs. Each plate retains its individual author and licence below.\n','Prepared PNGs preserve the full microscope field of view and scale bars. They are grayscale conversions, without generated or reconstructed image content. Preview derivatives are resized and dithered. Image derivatives retain the source licence listed for each plate.\n']
for e in entries:
 credits += [f"## {e['title']}\n",f"- Source: {e['source_page']}\n- Author: {e['credit']}\n- Licence: {e['license']} — {e['license_url']}\n- Changes: {e['changes']}\n- Magnification: {e['magnification'] or 'Not stated; no value inferred'}. File-label magnifications describe the original capture; resizing changes displayed magnification.\n"]
credits += ['\nTRMNL Framework assets are from https://trmnl.com/css/latest/plugins.css and https://trmnl.com/js/latest/plugins.js, retrieved 2026-10-17. Framework source: https://github.com/usetrmnl/trmnl-framework (MIT); see vendor/LICENSE-TRMNL.txt. Inter font: The Inter Project Authors (SIL OFL 1.1); see vendor/fonts/OFL-Inter.txt. TRMNL16: Heavyweight Digital Type Foundry (SIL OFL 1.1); see vendor/fonts/OFL-TRMNL16.txt. The snapshot is included for reproducible visual previews.\n']
(ROOT/'CREDITS.md').write_text('\n'.join(credits))
options=''.join(f'<option value="{html.escape(e["id"])}">{n+1:03d} · {html.escape(e["title"])}</option>' for n,e in enumerate(entries))
sheets=' · '.join(f'<a href="collection-{n+1:02d}-{min(n+10,len(entries)):02d}.png">Plates {n+1}–{min(n+10,len(entries))}</a>' for n in range(0,len(entries),10))
gallery='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unseen — collection review</title><style>body{font:16px system-ui,sans-serif;background:#e9e8e4;color:#171717;margin:0;padding:28px}main{max-width:1300px;margin:auto}h1{letter-spacing:.22em;font-size:26px;margin-bottom:8px}p{max-width:900px;line-height:1.5}select,button{font:inherit;padding:10px;margin:4px 8px 12px 0;max-width:100%}section{display:grid;grid-template-columns:1fr 1.3fr;gap:20px;align-items:start}img{width:100%;height:auto;display:block}label{font-weight:600}small{display:block;margin:10px 0;line-height:1.5}a{color:inherit}@media(max-width:800px){section{grid-template-columns:1fr}body{padding:16px}}</style><main><h1>Unseen</h1><p>A hidden world, every day. __COUNT__ real scanning electron micrographs, changing daily or on every refresh. Review the complete collection in locally simulated OG and X palettes.</p><label>Plate <select id="subject">__OPTIONS__</select></label><button id="next">Next plate →</button><section><div><h2>OG / 1-bit</h2><img id="og" alt="OG full-screen simulation"></div><div><h2>X / 16 grays</h2><img id="x" alt="TRMNL X full-screen simulation"></div></section><small>These are local rendering simulations. Live Every refresh advancement was verified in the authenticated TRMNL X full-screen preview on 18 October 2026: plate 003 to 004. These gallery images remain local simulations. The complete image field and original scale bars are preserved. Capture magnifications do not describe the resized display image.</small><p><a href="live-refresh-003.jpg">Live plate 003</a> · <a href="live-refresh-004.jpg">Live plate 004</a> · <a href="../CREDITS.md">Photo credits and licences</a> · <a href="../README.md">Setup and testing</a></p><p>__SHEETS__</p></main><script>const subject=document.querySelector('#subject');function refresh(){for(const p of ['og','x'])document.querySelector('#'+p).src=p+'-full-'+subject.value+'.png'}subject.onchange=refresh;document.querySelector('#next').onclick=()=>{subject.selectedIndex=(subject.selectedIndex+1)%subject.options.length;refresh()};refresh()</script></html>'''
(ROOT/'previews/index.html').write_text(gallery.replace('__COUNT__',str(len(entries))).replace('__OPTIONS__',options).replace('__SHEETS__',sheets))
print('Built four layouts, embedded catalogue and credits.')
